from client import convert

factors = {"m": 1.0, "cm": 0.01, "mm": 0.001, "km": 1000.0}
for source in factors:
    for target in factors:
        for value in (0.0, 1.0, -2.5, 123.456):
            assert convert(value, source, target) == value * factors[source] / factors[target]
assert convert(1.0, "km", "m") == 1000.0
assert convert(100.0, "cm", "m") == 1.0
